<script lang="ts">import AcademicEmptyState from '$lib/components/academic/AcademicEmptyState.svelte'; import AcademicErrorState from '$lib/components/academic/AcademicErrorState.svelte'; import SourceBadge from '$lib/components/academic/SourceBadge.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; let { data } = $props();</script>
